/// `gpf 12`. The `inline_c.h` macro of that name assembles to a different word,
/// so spell the instruction out.
#define gte_gpf12_real() __asm__ volatile("nop; nop; .word 0x4B98003D")

void func_actor_403200_801408D8(Task* arg0, s16 arg1, s16 arg2, s16 arg3)
{
    SVECTOR     dir;
    SVECTOR     normal;
    GpGridFace  face;
    GpGridFace  face2;
    SVECTOR*    verts;
    SVECTOR*    pool;
    GpGridFace* faces;
    SVECTOR*    d;

    pool  = Gp_GridParams->field_4;
    verts = Gp_GridParams->field_8;
    faces = Gp_GridParams->field_C;

    face.verts[0] = arg3 * 4;
    face.verts[1] = arg3 * 4 + 1;
    face.verts[2] = arg3 * 4 + 2;
    face.verts[3] = arg3 * 4 + 3;
    face.field_8  = arg3;
    face.field_A  = 3;

    face2.verts[0] = (arg3 + 1) * 4;
    face2.verts[1] = (arg3 + 1) * 4 + 1;
    face2.verts[2] = (arg3 + 1) * 4 + 2;
    face2.verts[3] = (arg3 + 1) * 4 + 3;
    face2.field_8  = arg3 + 1;
    face2.field_A  = 3;

    Gfx_MatrixCol2(&((TmdObject*)arg0->extra)->coords->coord, &normal);
    Gfx_MatrixCol0(&((TmdObject*)arg0->extra)->coords->coord, &dir);
    d = &dir;
    VectorNormalSS(d, d);
    VectorNormalSS(&normal, &normal);
    gte_lddp(arg1);
    gte_ldsv(&normal);
    gte_gpf12_real();
    gte_stsv(&normal);
    gte_lddp(0xBB8);
    gte_ldsv(d);
    gte_gpf12_real();
    gte_stsv(d);

    verts[arg3 * 4].vx = verts[arg3 * 4 + 2].vx =
        ((TmdObject*)arg0->extra)->coords->coord.t[0] + dir.vx + normal.vx;
    verts[arg3 * 4].vy = verts[arg3 * 4 + 2].vy =
        ((TmdObject*)arg0->extra)->coords->coord.t[1] + dir.vy + normal.vy;
    verts[arg3 * 4].vz = verts[arg3 * 4 + 2].vz =
        ((TmdObject*)arg0->extra)->coords->coord.t[2] + dir.vz + normal.vz;

    verts[arg3 * 4 + 1].vx = verts[arg3 * 4 + 3].vx =
        ((TmdObject*)arg0->extra)->coords->coord.t[0] + normal.vx;
    verts[arg3 * 4 + 1].vy = verts[arg3 * 4 + 3].vy =
        ((TmdObject*)arg0->extra)->coords->coord.t[1] + normal.vy;
    verts[arg3 * 4 + 1].vz = verts[arg3 * 4 + 3].vz =
        ((TmdObject*)arg0->extra)->coords->coord.t[2] + normal.vz;

    verts[(arg3 + 1) * 4].vx = verts[(arg3 + 1) * 4 + 2].vx =
        ((TmdObject*)arg0->extra)->coords->coord.t[0] + normal.vx;
    verts[(arg3 + 1) * 4].vy = verts[(arg3 + 1) * 4 + 2].vy =
        ((TmdObject*)arg0->extra)->coords->coord.t[1] + normal.vy;
    verts[(arg3 + 1) * 4].vz = verts[(arg3 + 1) * 4 + 2].vz =
        ((TmdObject*)arg0->extra)->coords->coord.t[2] + normal.vz;

    verts[(arg3 + 1) * 4 + 1].vx = verts[(arg3 + 1) * 4 + 3].vx =
        ((TmdObject*)arg0->extra)->coords->coord.t[0] + normal.vx - dir.vx;
    verts[(arg3 + 1) * 4 + 1].vy = verts[(arg3 + 1) * 4 + 3].vy =
        ((TmdObject*)arg0->extra)->coords->coord.t[1] + normal.vy - dir.vy;
    verts[(arg3 + 1) * 4 + 1].vz = verts[(arg3 + 1) * 4 + 3].vz =
        ((TmdObject*)arg0->extra)->coords->coord.t[2] + normal.vz - dir.vz;

    gte_lddp(0x3E8);
    gte_ldsv(&normal);
    gte_gpf12_real();
    gte_stsv(&normal);

    verts[arg3 * 4].vx = verts[arg3 * 4 + 2].vx += normal.vx;
    verts[arg3 * 4].vy = verts[arg3 * 4 + 2].vy += normal.vy;
    verts[arg3 * 4].vz = verts[arg3 * 4 + 2].vz += normal.vz;
    verts[arg3 * 4 + 5].vx = verts[arg3 * 4 + 7].vx += normal.vx;
    verts[arg3 * 4 + 5].vy = verts[arg3 * 4 + 7].vy += normal.vy;
    verts[arg3 * 4 + 5].vz = verts[arg3 * 4 + 7].vz += normal.vz;

    pool[arg3].vz = verts[arg3 * 4].vx - verts[arg3 * 4 + 1].vx;
    pool[arg3].vy = verts[arg3 * 4 + 1].vy - verts[arg3 * 4].vy;
    pool[arg3].vx = verts[arg3 * 4 + 1].vz - verts[arg3 * 4].vz;
    VectorNormalSS(&pool[arg3], &pool[arg3]);

    (&pool[arg3])[1].vz = verts[(arg3 + 1) * 4].vx - verts[(arg3 + 1) * 4 + 1].vx;
    (&pool[arg3])[1].vy = verts[(arg3 + 1) * 4 + 1].vy - verts[(arg3 + 1) * 4].vy;
    (&pool[arg3])[1].vx = verts[(arg3 + 1) * 4 + 1].vz - verts[(arg3 + 1) * 4].vz;
    VectorNormalSS(&(&pool[arg3])[1], &(&pool[arg3])[1]);

    verts[arg3 * 4].vy     -= arg2;
    verts[arg3 * 4 + 1].vy -= arg2;
    verts[arg3 * 4 + 4].vy -= arg2;
    verts[arg3 * 4 + 5].vy -= arg2;

    face.field_A  = 3;
    face2.field_A = 3;
    faces[arg3]     = face;
    faces[arg3 + 1] = face2;
}

